// Package: Azure.Messaging.EventGrid
using Azure.Messaging.EventGrid;
using System.Text.Json;

namespace BlogApi.Events;

public class BlogEventPublisher : IAsyncDisposable
{
    private readonly EventGridPublisherClient _client;
    private readonly JsonSerializerOptions _jsonOptions;

    public BlogEventPublisher(string topicEndpoint, string accessKey)
    {
        _client = new EventGridPublisherClient(
            new Uri(topicEndpoint),
            new AzureKeyCredential(accessKey));
        _jsonOptions = new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };
    }

    public async Task PublishPostPublishedAsync(
        Guid postId,
        string title,
        string author,
        DateTime publishedAt,
        CancellationToken cancellationToken = default)
    {
        var gridEvent = new EventGridEvent(
            subject: "/blog/posts/postId",
            eventType: "Blog.PostPublished",
            dataVersion: "1.0",
            data: new
            {
                postId = postId,
                title = title,
                author = author,
                publishedAt = publishedAt
            })
        {
            // Custom metadata for filtering subscribers
            DataVersion = "1.0"
        };

        await _client.SendEventAsync(gridEvent, cancellationToken);
    }

    public async Task PublishBatchAsync(
        IEnumerable<PostPublishedEvent> events,
        CancellationToken cancellationToken = default)
    {
        var gridEvents = events.Select(e => new EventGridEvent(
            subject: $"/blog/posts/{e.PostId}",
            eventType: "Blog.PostPublished",
            dataVersion: "1.0",
            data: e)).ToList();

        await _client.SendEventsAsync(gridEvents, cancellationToken);
    }

    public ValueTask DisposeAsync() => _client.DisposeAsync();
}

// --- Event record ---
public record PostPublishedEvent(Guid PostId, string Title, string Author, DateTime PublishedAt);

// --- Azure KeyCredential ---
// Package: Azure.Security.KeyVault.Keys.Cryptography (included in Azure.Messaging.EventGrid)
// Usage:
// var publisher = new BlogEventPublisher(topicEndpoint, accessKey);
// await publisher.PublishPostPublishedAsync(postId, title, author, publishedAt);
//
// Event Grid subscription filter (Azure portal or ARM template):
// Subject begins with: /blog/posts/
// Event types: Blog.PostPublished
// Endpoint: https://<function-app>.azurewebsites.net/api/HandleBlogEvent

// Package: Microsoft.Azure.Functions.Worker
// Package: Microsoft.Azure.Functions.Worker.Extensions.Http
// Package: Azure.Messaging.EventGrid
using System.Text.Json;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;
using Microsoft.Extensions.Logging;

namespace BlogApi.Functions;

public class HandleBlogEventFunction
{
    private readonly IBlogNotificationService _notificationService;
    private readonly ILogger<HandleBlogEventFunction> _logger;

    public HandleBlogEventFunction(
        IBlogNotificationService notificationService,
        ILogger<HandleBlogEventFunction> logger)
    {
        _notificationService = notificationService;
        _logger = logger;
    }

    [Function("handle-blog-event")]
    public async Task<HttpResponseData> RunAsync(
        [HttpTrigger(AuthorizationLevel.Function, "post", Route = "blog/events")]
        HttpRequestData req,
        CancellationToken cancellationToken)
    {
        // Event Grid subscription validation
        var body = await new StreamReader(req.Body).ReadToEndAsync(cancellationToken);
        using var doc = JsonDocument.Parse(body);
        var root = doc.RootElement;

        if (root.TryGetProperty("data", out var data) &&
            data.TryGetProperty("validationCode", out var code))
        {
            _logger.LogInformation("Validating Event Grid subscription...");
            var validationResponse = new
            {
                validationResponse = code.GetString()
            };
            var response = req.CreateResponse(System.Net.HttpStatusCode.OK);
            await response.WriteAsJsonAsync(validationResponse, cancellationToken);
            return response;
        }

        // Normal event processing — array of events
        if (root.TryGetProperty("data", out var eventData) &&
            root.TryGetProperty("eventType", out var eventType))
        {
            var type = eventType.GetString();
            _logger.LogInformation("Received event: {EventType}", type);

            if (type == "Blog.PostPublished")
            {
                var postEvent = eventData.Deserialize<PostPublishedEvent>();
                if (postEvent != null)
                {
                    await _notificationService.NotifySubscribersAsync(postEvent, cancellationToken);
                }
            }
        }

        return req.CreateResponse(System.Net.HttpStatusCode.OK);
    }
}

// --- Supporting types ---
// Package: Azure.Messaging.EventGrid
public record PostPublishedEvent(Guid PostId, string Title, string Author, DateTime PublishedAt);

public interface IBlogNotificationService
{
    Task NotifySubscribersAsync(PostPublishedEvent evt, CancellationToken ct);
}
